// Output Guardrail: Check AI response for dangerous content
const response = $input.first().json.output || $input.first().json.text || '';

// Dangerous patterns to check
const dangerousPatterns = {
  'destructive_command': /rm\s+-rf\s+\/|mkfs\.|dd\s+if=.*of=\/dev\//gi,
  'reverse_shell': /bash\s+-i\s+>&\s+\/dev\/tcp|nc\s+-e\s+\/bin\/(bash|sh)/gi,
  'sql_injection': /DROP\s+TABLE|DELETE\s+FROM\s+\w+\s*;|TRUNCATE\s+TABLE/gi,
  'credential_tool': /mimikatz|hashcat|john\s+the\s+ripper|hydra\s+-[lL]/gi,
  'privilege_escalation': /sudo\s+chmod\s+777|passwd\s+root|chmod\s+4755/gi
};

let guardrail_flags = [];
for (const [category, pattern] of Object.entries(dangerousPatterns)) {
  const matches = response.match(pattern);
  if (matches) {
    guardrail_flags.push({ category, count: matches.length });
  }
}

const guardrail_passed = guardrail_flags.length === 0;
const guardrail_status = guardrail_passed ? 'PASSED' : 'FLAGGED';

return [{
  json: {
    raw_response: response,
    guardrail_status,
    guardrail_passed,
    guardrail_flags,
    guardrail_message: guardrail_passed 
      ? 'AI output contains no dangerous content.' 
      : `WARNING: Detected ${guardrail_flags.map(f => f.category).join(', ')} in AI output.`
  }
}];

// Parse AI triage response
const response = $input.first().json.raw_response || '';
const guardrail_status = $input.first().json.guardrail_status;
const guardrail_message = $input.first().json.guardrail_message;
const guardrail_flags = $input.first().json.guardrail_flags;

let severity = 'Unknown';
let category = 'Unknown';
let summary = 'Unable to parse';
let actions = 'None specified';
let riskScore = 0;
let confidence = 0;

const severityMatch = response.match(/SEVERITY:\s*(Critical|High|Medium|Low)/i);
if (severityMatch) severity = severityMatch[1];

const categoryMatch = response.match(/CATEGORY:\s*([^\n]+)/i);
if (categoryMatch) category = categoryMatch[1].trim();

const summaryMatch = response.match(/SUMMARY:\s*([^\n]+)/i);
if (summaryMatch) summary = summaryMatch[1].trim();

const actionsMatch = response.match(/IMMEDIATE_ACTIONS:\s*([^\n]+)/i);
if (actionsMatch) actions = actionsMatch[1].trim();

const scoreMatch = response.match(/RISK_SCORE:\s*(\d+)/i);
if (scoreMatch) riskScore = parseInt(scoreMatch[1]);

const confMatch = response.match(/CONFIDENCE:\s*(\d+)/i);
if (confMatch) confidence = parseInt(confMatch[1]);

return [{
  json: {
    severity,
    category,
    summary,
    immediate_actions: actions,
    risk_score: riskScore,
    confidence,
    guardrail_status,
    guardrail_message,
    guardrail_flags,
    raw_response: response,
    timestamp: new Date().toISOString()
  }
}];

