// Parse validation response and generate audit log
const validationResponse = $input.first().json.output || $input.first().json.text || '';

let validation = 'Unknown';
let reason = 'Unable to parse';
let adjustedSeverity = 'Same';
let shouldRetry = 'No';

const validMatch = validationResponse.match(/VALIDATION:\s*(Correct|Incorrect)/i);
if (validMatch) validation = validMatch[1];

const reasonMatch = validationResponse.match(/REASON:\s*([^\n]+)/i);
if (reasonMatch) reason = reasonMatch[1].trim();

const adjMatch = validationResponse.match(/ADJUSTED_SEVERITY:\s*(Critical|High|Medium|Low|Same)/i);
if (adjMatch) adjustedSeverity = adjMatch[1];

const retryMatch = validationResponse.match(/SHOULD_RETRY:\s*(Yes|No)/i);
if (retryMatch) shouldRetry = retryMatch[1];

// Generate Decision Audit Log
const auditLog = {
  audit_id: `AUDIT-${Date.now()}`,
  timestamp: new Date().toISOString(),
  validation_result: validation,
  validation_reason: reason,
  adjusted_severity: adjustedSeverity,
  should_retry: shouldRetry,
  guardrail_check: 'PASSED',
  decision_trail: [
    'Step 1: Incident received and parsed',
    'Step 2: AI Triage Agent analyzed incident',
    'Step 3: Output Guardrail verified AI response safety',
    'Step 4: Severity-based routing applied',
    'Step 5: Decision Auditor reviewed assessment',
    `Step 6: Validation result - ${validation}`
  ]
};

return [{
  json: {
    ...auditLog,
    raw_validation: validationResponse,
    final_report: `\n============ FINAL SECURITY INCIDENT REPORT ============\n\n🔍 Decision Audit ID: ${auditLog.audit_id}\n⏰ Timestamp: ${auditLog.timestamp}\n\n✅ Validation: ${validation}\n📝 Reason: ${reason}\n🔄 Severity Adjustment: ${adjustedSeverity}\n🔁 Should Retry: ${shouldRetry}\n🛡️ Guardrail: PASSED\n\n📋 Decision Trail:\n${auditLog.decision_trail.map(s => '  ' + s).join('\n')}\n\n========================================================\n`
  }
}];
